  // Replace older copies of the exact same scan with the new verified web-friendly version.
  const photoKey=p=>String(p.year)+'|'+String(p.filename||'').toLowerCase();
  const updateKeys=new Set(photos.map(photoKey));
  db.photos=db.photos.filter(p=>!updateKeys.has(photoKey(p)) && String(p.year)!=='2024' && !(['2025','2026'].includes(String(p.year)) && p.kind==='team')).concat(photos);
  const norm=n=>String(n||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
  const rosterKeys=new Set(db.rosters.map(r=>String(r.year)+'|'+norm(r.name)));
  let added=0;
  for(const row of rosters){
    const key=row.year+'|'+norm(row.name);
    if(rosterKeys.has(key)) continue;
    db.rosters.push(row);
    rosterKeys.add(key);added++;
  }
  db.notes=db.notes||{};
  db.notes['2024']='Coach-confirmed 2024 varsity team. The original yearbook photo erroneously prints 2023; the photograph and all 12 captioned players are cataloged under 2024. The original image is preserved unaltered.';
  db.notes['2023']='No team is recorded for 2023 in the historical record book. The team photograph labeled 2023 was confirmed by the coach to be the 2024 team and is filed in 2024.';
  db.notes['1994']='The team caption prints initials only. Expanded full names proposed in earlier research are not certified by this photo; the original initials remain available for reference.';
  db.notes['2022']='The yearbook team caption includes a player identified only as Gibson. Her first name is not supplied in that caption.';
  db.archiveVersion='2026-11-17-all-time-caption-index-v4';
  db.importReport={sourceImages:115,publicPhotos:photos.length,verifiedRows:rosters.length,rowsAdded:added,reviewNeeded:['1994 roster initials','2022 first name for Gibson','remaining years without named roster']};
